/** Managed Project Brain (`agentos brain …`). See docs/brain.md.
 *
 * A record is a project-owned Markdown file whose YAML frontmatter carries `id: brain:<slug>` plus a small,
 * validated metadata set. The frontmatter is authoritative; `.agentos/brain/index.json` is derived from it and
 * regenerated by every brain write. Content is never copied: `register` adds or patches only the frontmatter
 * block, every other byte stays. Changes go through proposals (`propose` → `preview` / `validate` → `apply`);
 * AgentOS never calls a model. `source_hash` = sha256 of the body (everything after the frontmatter): a
 * different hash means "changed since verification", not "wrong".
 *
 * Writes: per-file atomic inside one in-process mutation transaction (same limits as checkpoints).
 */
import { createHash } from 'node:crypto';
import { lstat, readFile, readdir } from 'node:fs/promises';
import { basename, dirname, join, relative, resolve, sep } from 'node:path';
import { parseDocument, stringify as stringifyYaml } from 'yaml';
import { checkpointEvidence, loadCurrent, slugTask, type CheckpointContext } from './checkpoint.js';
import { automaticApproval, parseApprovalPolicy, AUTO_APPEND_BYTES, AUTO_RECORD_BYTES } from './brain-policy.js';
import { subjectOf, taskTerms, termHits } from './context-builder.js';
import { markdownHeadings } from './markdown.js';
import { assertRelativeBoundaryPath, isWithin } from './task-scope.js';
import { mkdirTracked, removeTracked, withMutationTransaction, writeFileAtomic, writeFileExclusiveAtomic } from './core.js';

export const KINDS = ['architecture', 'decision', 'adr', 'convention', 'feature', 'note'];
export const STATUSES = ['proposed', 'accepted', 'verified', 'superseded'];
/** Metadata keys plus four descriptive keys common in ADR/Obsidian notes. Anything else (task_scope, rules,
 *  permissions, engine settings) is refused: a Brain note is data, never instructions. */
export const RECORD_KEYS = ['id', 'kind', 'scope', 'status', 'sources', 'source_hash', 'verified_at', 'verified_by', 'supersedes', 'superseded_by', 'updated_at', 'history', 'title', 'date', 'tags', 'aliases'];
const PROPOSAL_KEYS = ['target', 'target_path', 'base_hash', 'proposed_by', 'status', 'mode', 'summary', 'supersedes', 'task', 'checkpoint', 'evidence', 'created_at', 'applied_at', 'applied_by', 'approval_mode', 'approval_policy_hash'];
export const BRAIN_DIR = '.agentos/brain';
const PROPOSALS = `${BRAIN_DIR}/proposals`;
const APPLIED = `${PROPOSALS}/applied`;
const INDEX = `${BRAIN_DIR}/index.json`;
const UNKNOWN = '(unknown — fill in)';
const MAX_BYTES = 100000;
const SINGLE_WRITER = 'One writer per workspace: proposals are applied one at a time under the workspace lock.';
const SKIP_DIRS = new Set(['.git', 'node_modules', 'dist', 'build', 'coverage', 'vendor', 'worktrees', '.worktrees']);
const SKIP_PATHS = new Set(['.agentos/runs', '.agentos/checkpoints', PROPOSALS, '.agentos/imports', '.agentos/skills', '.agentos/agents']);

export interface BrainRecord {
  id: string | null; path: string; kind: string | null; scope: string | null; status: string; state: 'ok' | 'changed' | 'invalid';
  title: string; source_hash: string | null; current_hash: string; fields: Record<string, any>; problems: string[]; body: string; text: string;
  /** `vault`: `path` (and `sources`) are vault-relative — the portable identity; `abs` is this machine's file. */
  location: 'workspace' | 'vault'; abs: string;
}
/** The linked Obsidian folder (`knowledge.obsidian` in project.yaml). `vault` is the machine-specific absolute
 *  binding and lives only in project.yaml; records under `dir` carry vault-relative paths. Records are walked
 *  there only when `canonical: vault` (records live in exactly one place; the other side holds links). */
export interface VaultBinding { vault: string; dest: string; dir: string; canonical: 'workspace' | 'vault' }
/** `vaultOff`: why the optional Obsidian integration is not used (disabled or invalid config); see docs/obsidian.md.
 *  `note`: the linked folder's index note (absolute path) and the project title for its heading, when one is configured. */
export interface BrainCtx { root: string; cwd: string; repos: string[]; vault?: VaultBinding | null; vaultOff?: string | null; note?: { abs: string; name: string } | null; approval?: unknown; evidence?: Pick<CheckpointContext, 'repos' | 'excluded'> }

const sha256 = (text: string) => createHash('sha256').update(text).digest('hex');
const norm = (text: string) => text.replace(/\s+/g, ' ').trim();
const posix = (path: string) => path.split(sep).join('/');
const short = (hash: string | null) => (hash ?? '').slice(0, 8) || '(none)';

// --- frontmatter ------------------------------------------------------------------------------------

/** head = `---\n`, fm = metadata text, close = the closing `---` line, body = every byte after it. */
export function splitFrontmatter(text: string) {
  const nl = text.includes('\r\n') ? '\r\n' : '\n';
  const open = text.match(/^---(\r?\n)/);
  if (!open) return { has: false, closed: false, nl, head: '', fm: '', close: '', body: text };
  const rest = text.slice(open[0].length);
  const close = rest.match(/^---[ \t]*(?:\r?\n|$)/m);
  if (!close) return { has: true, closed: false, nl: open[1], head: open[0], fm: rest, close: '', body: '' };
  return { has: true, closed: true, nl: open[1], head: open[0], fm: rest.slice(0, close.index), close: close[0], body: rest.slice(close.index + close[0].length) };
}

const keyLine = (fm: string, key: string) => fm.split(/\r?\n/).findIndex((line) => new RegExp(`^${key}\\s*:`).test(line)) + 2;

/** Parse a frontmatter block against an allowlist. Problems carry `<path>:<line>`. */
function parseFields(rel: string, fm: string, allowed: string[]) {
  const problems: string[] = [];
  const doc = parseDocument(fm);
  if (doc.errors.length) {
    for (const error of doc.errors) problems.push(`${rel}:${(error.linePos?.[0]?.line ?? 1) + 1}: invalid YAML: ${error.message.split('\n')[0]}`);
    return { fields: {}, problems };
  }
  const fields = doc.toJS() ?? {};
  if (typeof fields !== 'object' || Array.isArray(fields)) return { fields: {}, problems: [`${rel}:2: frontmatter must be a mapping`] };
  for (const key of Object.keys(fields)) if (!allowed.includes(key)) problems.push(`${rel}:${keyLine(fm, key)}: unknown key ${key} (allowed keys: ${allowed.join(', ')})`);
  return { fields, problems };
}

/** Line blocks of top-level keys: `key:` at column 0 plus its indented / `- ` continuation lines. */
function keyBlocks(lines: string[]) {
  const blocks: Array<{ key: string; start: number; end: number }> = [];
  lines.forEach((line, index) => {
    const key = line.match(/^([A-Za-z_][\w-]*)\s*:/);
    if (key) blocks.push({ key: key[1], start: index, end: index });
    else if (blocks.length && blocks.at(-1).end === index - 1 && /^(\s+\S|- )/.test(line)) blocks.at(-1).end = index;
  });
  return blocks;
}

const renderKey = (key: string, value: any) => stringifyYaml({ [key]: value }, { lineWidth: 0 }).trimEnd().split('\n');

/** Set top-level keys by replacing each key's own line block (or appending it before the closing line);
 *  comments, order and every other line stay byte-identical. No frontmatter yet: prepend one. */
export function patchFrontmatter(text: string, updates: Record<string, any>) {
  const split = splitFrontmatter(text);
  const nl = split.nl;
  if (!split.has) return `---${nl}${Object.entries(updates).flatMap(([key, value]) => renderKey(key, value)).join(nl)}${nl}---${nl}${text}`;
  if (!split.closed) throw new Error('frontmatter is not closed; nothing was written');
  const lines = split.fm ? split.fm.replace(/\r?\n$/, '').split(/\r?\n/) : [];
  for (const [key, value] of Object.entries(updates)) {
    const found = keyBlocks(lines).filter((block) => block.key === key);
    if (found.length > 1) throw new Error(`frontmatter key ${key} appears twice; fix it by hand, nothing was written`);
    const rendered = renderKey(key, value);
    if (found.length) lines.splice(found[0].start, found[0].end - found[0].start + 1, ...rendered);
    else lines.push(...rendered);
  }
  return `${split.head}${lines.join(nl)}${nl}${split.close}${split.body}`;
}

// --- records ----------------------------------------------------------------------------------------

const isBrainCandidate = (text: string) => { const split = splitFrontmatter(text); return split.has && /^id\s*:\s*["']?brain:/m.test(split.fm); };

export function parseRecord(rel: string, text: string, repos: string[], location: 'workspace' | 'vault' = 'workspace', abs = ''): BrainRecord {
  const split = splitFrontmatter(text);
  const current_hash = sha256(split.body);
  const h1 = markdownHeadings(split.body).find((heading) => heading.level === 1)?.title;
  const base = { path: rel, current_hash, body: split.body, text, location, abs };
  if (!split.closed) return { ...base, id: null, kind: null, scope: null, status: 'invalid', state: 'invalid', title: h1 ?? basename(rel), source_hash: null, fields: {}, problems: [`${rel}:1: frontmatter is not closed (no terminating --- line)`] };
  const { fields, problems } = parseFields(rel, split.fm, RECORD_KEYS);
  const at = (key: string) => `${rel}:${keyLine(split.fm, key) || 2}`;
  const str = (value: unknown) => typeof value === 'string' && value.length > 0;
  const ids = (value: unknown) => value === undefined || (Array.isArray(value) ? value : [value]).every((id) => typeof id === 'string' && /^brain:[a-z0-9][a-z0-9-]*$/.test(id));
  if (!problems.length) {
    if (!str(fields.id) || !/^brain:[a-z0-9][a-z0-9-]*$/.test(fields.id)) problems.push(`${at('id')}: id must be brain:<slug>`);
    if (!KINDS.includes(fields.kind)) problems.push(`${at('kind')}: kind must be one of ${KINDS.join('|')}`);
    if (!STATUSES.includes(fields.status)) problems.push(`${at('status')}: status must be one of ${STATUSES.join('|')}`);
    if (!str(fields.scope) || (fields.scope !== '.' && !repos.includes(fields.scope))) problems.push(`${at('scope')}: scope must be . or a repo id from project.yaml (${repos.join(', ') || 'none'})`);
    if (!Array.isArray(fields.sources) || !fields.sources.every(str)) problems.push(`${at('sources')}: sources must be a list of ${location}-relative paths`);
    else if (!fields.sources.includes(rel)) problems.push(`${at('sources')}: sources does not list this file (${rel}); was it moved or copied?`);
    if (!str(fields.source_hash) || !/^[a-f0-9]{64}$/.test(fields.source_hash)) problems.push(`${at('source_hash')}: source_hash must be a sha256 hex digest`);
    if (!ids(fields.supersedes)) problems.push(`${at('supersedes')}: supersedes must be brain ids`);
    if (fields.superseded_by !== undefined && !ids(fields.superseded_by)) problems.push(`${at('superseded_by')}: superseded_by must be a brain id`);
    if (fields.history !== undefined && (!Array.isArray(fields.history) || !fields.history.every(str))) problems.push(`${at('history')}: history must be a list of strings`);
    for (const key of ['verified_at', 'verified_by', 'updated_at', 'title']) if (fields[key] !== undefined && !str(fields[key])) problems.push(`${at(key)}: ${key} must be a string`);
  }
  const invalid = problems.length > 0;
  return {
    ...base, fields, problems,
    id: str(fields.id) ? fields.id : null, kind: fields.kind ?? null, scope: fields.scope ?? null,
    status: invalid ? 'invalid' : fields.status, state: invalid ? 'invalid' : fields.source_hash === current_hash ? 'ok' : 'changed',
    title: str(fields.title) ? fields.title : h1 ?? basename(rel, '.md'), source_hash: str(fields.source_hash) ? fields.source_hash : null,
  };
}

/** A directory or file the walk could not read (permission or I/O failure; never an absent path). */
export interface Unreadable { path: string; location: 'workspace' | 'vault'; code: string }
export type BrainRecords = BrainRecord[] & { unreadable?: Unreadable[] };
export const ioReason = (code: string) => `${code}: ${code === 'EACCES' || code === 'EPERM' ? 'permission denied' : 'I/O error'}`;

/** `ok` | `empty` | `absent` (ENOENT/ENOTDIR: removed, renamed or not mounted) | the error code (EACCES, EIO, …). */
export async function dirState(dir: string) {
  try { return (await readdir(dir)).length ? 'ok' : 'empty'; } catch (error) { return ['ENOENT', 'ENOTDIR'].includes(error.code) ? 'absent' : error.code ?? 'EIO'; }
}

/** Every Markdown file in the workspace whose frontmatter declares `id: brain:…`. Symlinks are not followed.
 *  A directory or file that cannot be read is listed in `.unreadable` — never read as empty (F9).
 *  ponytail: a full walk on every read (skipping vendored/build/state dirs); use index.json as a cache if it gets slow. */
export async function loadBrain(root: string, repos: string[], vault?: VaultBinding | null): Promise<BrainRecords> {
  const records: BrainRecords = [];
  const unreadable: Unreadable[] = [];
  const inVault = vault?.canonical === 'vault';
  const vaultInWorkspace = inVault ? posix(relative(root, vault.dir)) : null; // walked once, as vault records
  const fail = (path: string, location: 'workspace' | 'vault', error: any) => { if (error.code !== 'ENOENT') unreadable.push({ path, location, code: error.code ?? 'EIO' }); };
  // `top`: the linked vault folder itself is reported by vaultUnavailable, not here.
  async function walk(base: string, rel: string, location: 'workspace' | 'vault', top = false) {
    let entries;
    try { entries = await readdir(join(base, rel), { withFileTypes: true }); } catch (error) { if (!top) fail(rel || '.', location, error); return; }
    // A nested folder with its own `.agentos/` is another workspace with its own Brain: never read its records here.
    if (location === 'workspace' && rel && entries.some((entry) => entry.name === '.agentos' && entry.isDirectory())) return;
    for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
      const path = rel ? `${rel}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        if (SKIP_DIRS.has(entry.name) || (entry.name.startsWith('.') && !(location === 'workspace' && path === '.agentos'))) continue;
        if (location === 'workspace' && (SKIP_PATHS.has(path) || path === vaultInWorkspace)) continue;
        await walk(base, path, location);
      } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
        const abs = join(base, path);
        let text;
        try { if ((await lstat(abs)).size > 1024 * 1024) continue; text = await readFile(abs, 'utf8'); } catch (error) { fail(path, location, error); continue; }
        if (isBrainCandidate(text)) records.push(parseRecord(path, text, repos, location, abs));
      }
    }
  }
  await walk(root, '', 'workspace');
  if (inVault) await walk(vault.vault, vault.dest === '.' ? '' : vault.dest, 'vault', true);
  records.unreadable = unreadable;
  const seen = new Map<string, BrainRecord>();
  for (const record of records) {
    if (!record.id || record.state === 'invalid') continue;
    const other = seen.get(record.id);
    if (!other) { seen.set(record.id, record); continue; }
    for (const dup of [other, record]) { dup.problems.push(`${dup.path}:${keyLine(splitFrontmatter(dup.text).fm, 'id')}: duplicate id ${record.id} (${other.path}, ${record.path})`); dup.state = 'invalid'; dup.status = 'invalid'; }
  }
  return records;
}

const valid = (records: BrainRecord[]) => records.filter((record) => record.state !== 'invalid');
const inside = isWithin;

/** Where a path may hold a record: the workspace, or (canonical: vault) the linked folder — never the rest of the vault. */
function classify(ctx: BrainCtx, abs: string): { location: 'workspace' | 'vault'; base: string } | { refused: string } | null {
  const v = ctx.vault;
  if (v && inside(v.dir, abs) && v.canonical === 'vault') return { location: 'vault', base: v.vault };
  if (inside(ctx.root, abs)) return { location: 'workspace', base: ctx.root };
  if (v && inside(v.dir, abs)) return { refused: `${abs}: knowledge.obsidian.canonical is workspace, so records live in the workspace and the vault folder holds links only (no copies). Set canonical: vault in .agentos/project.yaml to keep records in ${v.dir}. Nothing was written.` };
  if (v && inside(v.vault, abs)) return { refused: `${abs} is inside the vault but outside the linked folder ${v.dir}; only that folder is allowed. Nothing was written.` };
  return null;
}

function findRecord(records: BrainRecord[], ctx: BrainCtx, ref: string) {
  const byId = records.find((record) => record.id === ref);
  if (byId) return byId;
  const abs = resolve(ctx.cwd, ref);
  const where = classify(ctx, abs);
  if (where && 'refused' in where) throw new Error(where.refused);
  return records.find((record) => record.abs === abs);
}

/** Context builder input: valid records only (doctor reports the invalid ones). Vault records are referenced
 *  by this machine's absolute path (the reader needs a real file), workspace records by their relative path. */
export function brainContextRecords(records: BrainRecord[]) {
  return valid(records).map((record) => ({ id: record.id, kind: record.kind, status: record.status, scope: record.scope, title: record.title, path: record.location === 'vault' ? record.abs : record.path, location: record.location, changed: record.state === 'changed' }));
}

/** index.json entries: derived, but the only list of record identities that survives their storage going away. */
async function lastKnown(root: string): Promise<any[]> {
  try { return JSON.parse(await readFile(join(root, INDEX), 'utf8')).records ?? []; } catch { return []; }
}
const shown = (entry: any, state: string) => ({ id: entry.id, kind: entry.kind, status: entry.status, scope: entry.scope, title: entry.title, path: entry.path, location: entry.location ?? 'workspace', state });

/** Vault records that cannot be read now. The linked folder is absent (vault unmounted, renamed, removed), unreadable
 *  (permission/I/O failure), empty while index.json still lists records there (an empty mount point), or the integration
 *  is off (`off`: disabled or invalid config) so the folder is not walked. `required`: the folder is the canonical store
 *  (canonical: vault), so its absence is missing knowledge, not just a missing viewer. `failed`: an I/O error. */
export async function vaultUnavailable(root: string, vault?: VaultBinding | null, off?: string | null, known?: any[]) {
  const state = off || !vault ? null : await dirState(vault.dir);
  if (!off && (!vault || state === 'ok')) return null;
  const entries = (known ?? await lastKnown(root)).filter((record: any) => record.location === 'vault');
  if ((off || state === 'empty') && !entries.length) return null;
  const reason = off ?? (state === 'absent' ? `vault unavailable: ${vault.dir}`
    : state === 'empty' ? `vault folder empty: ${vault.dir} (${entries.length} record(s) last known there; not mounted, or moved?)`
      : `vault unreadable: ${vault.dir} (${ioReason(state)})`);
  return { vault: true, dir: off ? null : vault.dir, reason, absent: state === 'absent', failed: Boolean(state) && !['absent', 'empty'].includes(state), required: !off && vault.canonical === 'vault', entries, records: entries.map((entry) => shown(entry, 'unavailable')) };
}
type Gone = NonNullable<Awaited<ReturnType<typeof vaultUnavailable>>>;

/** Everything that cannot be read now: the vault folder (above) plus every unreadable path the walk met, each with
 *  the records index.json last knew under it — identities are kept and reported, never dropped as if deleted. */
async function unreadableKnowledge(root: string, records: BrainRecords, vault?: VaultBinding | null, off?: string | null): Promise<Gone[]> {
  const known = await lastKnown(root);
  const gone = await vaultUnavailable(root, vault, off, known);
  return [...(gone ? [gone] : []), ...(records.unreadable ?? []).map((u) => {
    const entries = known.filter((entry) => (entry.location ?? 'workspace') === u.location && (u.path === '.' || entry.path === u.path || entry.path.startsWith(`${u.path}/`)));
    return { vault: false, dir: u.path, reason: `${u.location === 'vault' ? `${vault?.dir}/` : ''}${u.path} is unreadable (${ioReason(u.code)})`, absent: false, failed: true, required: false, entries, records: entries.map((entry) => shown(entry, 'unreadable')) };
  })];
}

/** `context` input: required knowledge that cannot be read right now (never an optional viewer on its own). */
export async function brainMissing(root: string, records: BrainRecords, vault?: VaultBinding | null, off?: string | null) {
  return (await unreadableKnowledge(root, records, vault, off)).flatMap((gone) => [...(gone.required ? [gone.reason] : []), ...gone.records.map((record) => `${record.id} (${record.path}): ${gone.reason}`)]);
}

const indexEntry = (record: BrainRecord) => ({ id: record.id, kind: record.kind, status: record.status, scope: record.scope, title: record.title, path: record.path, ...(record.location === 'vault' ? { location: 'vault' } : {}), source_hash: record.source_hash, ...(record.fields.superseded_by ? { superseded_by: record.fields.superseded_by } : {}) });

function indexContent(records: BrainRecord[], kept: any[] = []) {
  return `${JSON.stringify({
    schema: 'agentos.brain-index/1',
    note: 'Derived from record frontmatter by agentos brain; never authoritative. Safe to delete; the next brain write or `agentos brain index` regenerates it.',
    records: [...valid(records).map(indexEntry), ...kept],
    invalid: records.filter((record) => record.state === 'invalid').map((record) => record.path),
  }, null, 2)}\n`;
}

/** Regenerate index.json; written only when its bytes change (no churn). Records that cannot be read now (vault
 *  folder gone/unreadable, integration off, unreadable directory) keep their last known entries. */
async function writeIndex(ctx: BrainCtx, records: BrainRecords, dryRun = false) {
  const content = indexContent(records, (await unreadableKnowledge(ctx.root, records, ctx.vault, ctx.vaultOff)).flatMap((gone) => gone.entries));
  const before = await readFile(join(ctx.root, INDEX), 'utf8').catch(() => null);
  const action = before === null ? 'create' : before === content ? 'unchanged' : 'refresh';
  if (!dryRun && action !== 'unchanged') await withMutationTransaction(async () => { await mkdirTracked(join(ctx.root, BRAIN_DIR)); await writeFileAtomic(join(ctx.root, INDEX), content); });
  return action;
}

// --- Obsidian index note -----------------------------------------------------------------------------
// The note `obsidian init|link` creates holds human prose plus one generated block between two markers; only the
// block is rewritten (every Brain write, `agentos brain index`). A note without markers (AgentOS 1.1 and earlier) is never
// changed without `brain index --adopt`, whose preview `brain index` prints.

const NOTE_START = '<!-- agentos:brain-index:start (generated by agentos brain; edits inside this block are replaced) -->';
const NOTE_END = '<!-- agentos:brain-index:end -->';
const START_PREFIX = '<!-- agentos:brain-index:start';
const LEGACY_PROMISE = 'Written once by `agentos obsidian init|link`; AgentOS never overwrites it. Edit it freely.';
const NOTE_RULE = 'AgentOS rewrites only the block between the `agentos:brain-index` markers (on every Brain write and `agentos brain index`); everything else in this note is yours.';
const NONE_YET = '- None registered yet (`agentos brain init`, `agentos brain register <path>`).';
const OUTSIDE = ' — outside this vault: edit in your editor';
const OUTSIDE_RULE = 'Obsidian shows only records stored inside this vault folder. A record marked *outside this vault* lives in the workspace (for example `.agentos/`): Obsidian cannot open it; edit it in your editor or through `agentos brain propose|apply`. To have a new record editable here, create it inside this folder and register it in place: `agentos brain register <this folder>/<note>.md` (no copies, no moves).';
const GENERATED_LINE = /^- \[.*\]\(<.*>\) — `brain:[a-z0-9-]+` \([a-z]+, [a-z]+\)( — outside this vault: edit in your editor)?$/;

/** The generated block: a link (relative to the note) to every valid record, in walk order; records outside the
 *  vault folder Obsidian opens (`vaultRoot`) are marked, since Obsidian cannot open links that leave it (D3). Deterministic. */
function noteBlock(records: BrainRecord[], noteAbs: string, vaultRoot: string) {
  const list = valid(records).map((record) => `- [${record.title}](<${posix(relative(dirname(noteAbs), record.abs))}>) — \`${record.id}\` (${record.kind}, ${record.status})${inside(vaultRoot, record.abs) ? '' : OUTSIDE}`);
  return [NOTE_START, '## Brain records', '', ...(list.some((line) => line.endsWith(OUTSIDE)) ? [OUTSIDE_RULE, ''] : []), ...(list.length ? list : [NONE_YET]), NOTE_END].join('\n');
}

/** A new index note (`obsidian init|link`, or recovery after it was deleted). In an external vault with
 *  canonical: workspace it is a navigation note only: labelled as such, in frontmatter and text. */
export function newIndexNote(name: string, canonical: string, records: BrainRecord[], noteAbs: string, root: string, vaultRoot = dirname(noteAbs)) {
  const navigation = canonical === 'workspace' && !inside(root, noteAbs);
  return [
    ...(navigation ? ['---', 'tags: [agentos-navigation]', '---', ''] : []),
    `# ${name} AgentOS Index`, '', NOTE_RULE, '',
    ...(navigation ? ['**Navigation only.** The records below live in the AgentOS workspace, outside this vault; this vault does not contain or sync them, and Obsidian may not open links that leave the vault. Obsidian edits only records stored inside the vault it opens.', ''] : []),
    `Canonical location of the Project Brain: **${canonical}**. Records live there only; this note holds links, never copies (no sync).`,
    'Runtime state stays in the workspace `.agentos/`. Agents read only the notes a task needs, never the whole vault, and change records only through `agentos brain register|propose|apply`.', '',
    noteBlock(records, noteAbs, vaultRoot), '',
  ].join('\n');
}

/** Adopt an unmarked note: its `## Brain records` section is replaced only when every line in it is one AgentOS
 *  generated; otherwise the block is appended and the hand-written section stays. Nothing else changes. */
function adoptNote(before: string, block: string) {
  const lines = before.replace(LEGACY_PROMISE, NOTE_RULE).split('\n');
  const at = lines.indexOf('## Brain records');
  let end = at + 1;
  while (at >= 0 && end < lines.length && !lines[end].startsWith('#')) end++;
  if (at >= 0 && lines.slice(at + 1, end).every((line) => line === '' || line === NONE_YET || line === OUTSIDE_RULE || GENERATED_LINE.test(line))) {
    return [...lines.slice(0, at), ...block.split('\n'), '', ...lines.slice(end)].join('\n').replace(/\n*$/, '\n');
  }
  const text = lines.join('\n');
  return `${text}${text.endsWith('\n') ? '' : '\n'}\n${block}\n`;
}

const NOTE_WRITES = new Set(['create', 'refresh', 'adopt']);

/** What the index note needs: create (absent), refresh/unchanged (one marker pair), legacy (no markers; `adopt` to
 *  write), broken (damaged markers: never written). Null: no index note is linked, or its folder is absent. */
async function planNote(ctx: BrainCtx, records: BrainRecords, adopt: boolean) {
  const note = ctx.note;
  if (!note || !ctx.vault || await dirState(dirname(note.abs)) === 'absent') return null;
  const rel = inside(ctx.root, note.abs) ? posix(relative(ctx.root, note.abs)) : note.abs;
  const before = await readFile(note.abs, 'utf8').catch((error) => { if (error.code === 'ENOENT') return null; throw error; });
  if (before === null) return { rel, abs: note.abs, before, after: newIndexNote(note.name, ctx.vault.canonical, records, note.abs, ctx.root, ctx.vault.vault), action: 'create' };
  const block = noteBlock(records, note.abs, ctx.vault.vault);
  const starts = before.split(START_PREFIX).length - 1, ends = before.split(NOTE_END).length - 1;
  const s = before.indexOf(START_PREFIX), e = before.indexOf(NOTE_END);
  if (starts === 1 && ends === 1 && s < e) {
    const after = `${before.slice(0, s)}${block}${before.slice(e + NOTE_END.length)}`;
    return { rel, abs: note.abs, before, after, action: after === before ? 'unchanged' : 'refresh' };
  }
  if (starts || ends) return { rel, abs: note.abs, before, after: null, action: 'broken' };
  return { rel, abs: note.abs, before, after: adoptNote(before, block), action: adopt ? 'adopt' : 'legacy' };
}

const legacyLine = (rel: string) => `index note ${rel} has no agentos:brain-index markers (an older note); not refreshed. Preview: \`agentos brain index\`; adopt: \`agentos brain index --adopt\` (text outside the generated block is kept).`;
const brokenLine = (rel: string) => `index note ${rel} has damaged agentos:brain-index markers (exactly one start and one end marker are needed); not refreshed. Fix the markers by hand; nothing was written to it.`;

/** Plan and (unless dryRun) write the index note. A failure never throws: the note is optional and derived. */
async function syncNote(ctx: BrainCtx, records: BrainRecords, adopt = false, dryRun = false) {
  let plan = null;
  try {
    plan = await planNote(ctx, records, adopt);
    if (plan && !dryRun && NOTE_WRITES.has(plan.action)) await withMutationTransaction(() => writeFileAtomic(plan.abs, plan.after));
  } catch (error) {
    return { plan, failed: true, lines: [`Warning: index note ${plan?.rel ?? ctx.note?.abs} is stale (${error.message}); the record write above is kept. The next successful brain write or \`agentos brain index\` regenerates it.`] };
  }
  const lines = plan?.action === 'legacy' ? [`Warning: ${legacyLine(plan.rel)}`] : plan?.action === 'broken' ? [`Warning: ${brokenLine(plan.rel)}`] : [];
  return { plan, failed: false, lines };
}

/** A Brain write, then the derived index.json and index note, each in its own transaction. Both are rebuildable, so
 *  their failure keeps the record write and is reported as stale (lines + flags) instead of rolling the knowledge back. */
const NO_COMMIT = { lines: [] as string[], flags: {} as Record<string, true> };
async function commit(ctx: BrainCtx, write: () => Promise<void>) {
  await withMutationTransaction(write);
  const lines: string[] = [], flags: Record<string, true> = {};
  let records: BrainRecords | null = null;
  try { records = await loadBrain(ctx.root, ctx.repos, ctx.vault); await writeIndex(ctx, records); }
  catch (error) { flags.index_stale = true; lines.push(`Warning: ${INDEX} is stale (${error.message}); the record write above is kept. The index is derived: the next successful brain write or \`agentos brain index\` regenerates it.`); }
  if (records) {
    const note = await syncNote(ctx, records);
    if (note.lines.length) { flags.note_stale = true; lines.push(...note.lines); }
  }
  return { lines, flags };
}

/** `agentos brain index`: recreate or refresh the derived index.json and index note from the records (recovery after
 *  either was deleted; preview/adoption of an unmarked note). Never touches records, config or history. */
export async function indexBrain(ctx: BrainCtx, options: { adopt?: boolean; dryRun?: boolean; json?: boolean }) {
  const records = await loadBrain(ctx.root, ctx.repos, ctx.vault);
  const dry = Boolean(options.dryRun);
  const verb = (action: string) => ({ create: dry ? 'Would create' : 'Created', refresh: dry ? 'Would refresh' : 'Refreshed', adopt: dry ? 'Would adopt' : 'Adopted', unchanged: 'Unchanged' })[action];
  const index = await writeIndex(ctx, records, dry);
  const note = await syncNote(ctx, records, Boolean(options.adopt), dry);
  const plan = note.plan;
  const ok = !note.failed && plan?.action !== 'broken';
  const lines = [
    `AgentOS brain index${dry ? ' (dry run)' : ''}`,
    `- ${verb(index)}: ${INDEX} (${valid(records).length} record(s))`,
    ...(!ctx.note ? ['- No Obsidian index note is linked; nothing else to do.'] : !plan && !note.failed ? [`- Index note folder ${dirname(ctx.note.abs)} is absent; the note was not written (see \`agentos obsidian status\`).`] : []),
    ...(plan && (NOTE_WRITES.has(plan.action) || plan.action === 'unchanged') ? [`- ${verb(plan.action)}: index note ${plan.rel}`] : []),
    ...(plan?.action === 'legacy' ? [`- ${legacyLine(plan.rel)}`, 'Preview of --adopt:', ...diffLines(plan.before, plan.after)] : []),
    ...(plan?.action === 'adopt' ? ['Diff:', ...diffLines(plan.before, plan.after)] : []),
    ...(plan?.action === 'broken' ? [`- ${brokenLine(plan.rel)}`] : []),
    ...(note.failed ? note.lines : []),
    'Records, project.yaml and history are never changed by this command.',
  ];
  return out(options.json, ok, { dryRun: dry, index, note: plan ? { path: plan.rel, action: plan.action } : null, ...(note.failed ? { note_stale: true } : {}) }, lines);
}

const out = (json: boolean, ok: boolean, data: any, lines: string[]) => ({ ok, ...data, text: json ? JSON.stringify({ ok, ...data }, null, 2) : lines.join('\n') });
const publicRecord = (record: BrainRecord) => ({ id: record.id, kind: record.kind, status: record.status, scope: record.scope, title: record.title, path: record.path, state: record.state, ...(record.location === 'vault' ? { location: 'vault', abs: record.abs } : {}) });

// --- register / init --------------------------------------------------------------------------------

const slug = (text: string) => text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const defaultKind = (rel: string) => (/(^|\/)adrs?\//i.test(rel) ? 'adr' : basename(rel) === 'decisions.md' ? 'decision' : 'note');

/** Inside the workspace root or (canonical: vault) the linked folder, not in .git or a dot folder of the vault,
 *  Markdown, a regular file reached without symlinks. Returns the location-relative path and the absolute file. */
async function assertRegistrable(ctx: BrainCtx, pathArg: string) {
  const abs = resolve(ctx.cwd, pathArg);
  const where = classify(ctx, abs);
  if (where && 'refused' in where) throw new Error(where.refused);
  const base = where && 'base' in where ? where.base : ctx.root;
  const location = where && 'location' in where ? where.location : 'workspace';
  const rel = posix(relative(base, abs));
  try { assertRelativeBoundaryPath(rel); } catch { throw new Error(`${pathArg} is outside the workspace root; only project-owned files can be registered.`); }
  if (rel.split('/').includes('.git')) throw new Error(`${rel} is inside .git; refused.`);
  if (location === 'vault' && rel.split('/').some((part) => part.startsWith('.'))) throw new Error(`${rel} is inside a dot folder of the vault (e.g. .obsidian/); refused.`);
  if (!/\.md$/i.test(rel)) throw new Error(`${rel} is not a Markdown (.md) file; refused.`);
  if (rel === PROPOSALS || rel.startsWith(`${PROPOSALS}/`)) throw new Error(`${rel} is a proposal, not a record.`);
  const parts = rel.split('/');
  for (let i = 1; i <= parts.length; i++) {
    let info;
    try { info = await lstat(join(base, ...parts.slice(0, i))); } catch { throw new Error(`${rel} does not exist; register an existing file.`); }
    if (info.isSymbolicLink()) throw new Error(`${parts.slice(0, i).join('/')} is a symlink; refused.`);
    if (i === parts.length && !info.isFile()) throw new Error(`${rel} is not a regular file.`);
  }
  return { rel, abs: join(base, rel), location };
}

async function readUtf8(path: string) {
  const bytes = await readFile(path);
  if (bytes.length > MAX_BYTES) throw new Error(`${path} is larger than ${MAX_BYTES} bytes.`);
  try { return new TextDecoder('utf-8', { fatal: true }).decode(bytes); } catch { throw new Error(`${path} is not valid UTF-8.`); }
}

interface RegisterOptions { kind?: string; scope?: string; status?: string; by?: string; dryRun?: boolean; json?: boolean }

/** Plan a registration: the patched text, the keys it adds and the conflicts it keeps. Throws on refusal. */
async function planRegister(ctx: BrainCtx, records: BrainRecord[], pathArg: string, options: RegisterOptions) {
  const { rel, abs, location } = await assertRegistrable(ctx, pathArg);
  const text = await readUtf8(abs);
  const split = splitFrontmatter(text);
  if (split.has && !split.closed) throw new Error(`${rel}:1: frontmatter is not closed; fix it by hand. Nothing was written.`);
  const existing = split.has ? parseFields(rel, split.fm, RECORD_KEYS) : { fields: {}, problems: [] };
  if (existing.problems.length) throw new Error(`${existing.problems.join('\n')}\nNothing was written.`);
  const fields: Record<string, any> = existing.fields;
  if (options.kind !== undefined && !KINDS.includes(options.kind)) throw new Error(`--kind must be one of ${KINDS.join('|')}`);
  if (options.status !== undefined && !['proposed', 'accepted'].includes(options.status)) throw new Error('--status must be proposed or accepted (verify sets verified; apply sets superseded).');
  const scope = options.scope ?? '.';
  if (scope !== '.' && !ctx.repos.includes(scope)) throw new Error(`--scope must be . or a repo id from project.yaml (${ctx.repos.join(', ') || 'none'}).`);
  let id = fields.id;
  if (!id) {
    id = `brain:${slug(basename(rel, '.md'))}`;
    if (records.some((record) => record.id === id && record.abs !== abs)) id = `brain:${slug(rel.replace(/\.md$/i, ''))}`;
  }
  if (records.some((record) => record.id === id && record.abs !== abs)) throw new Error(`id ${id} is already used by ${records.find((record) => record.id === id).path}.`);
  const now = new Date().toISOString();
  const desired: Record<string, any> = {
    id, kind: options.kind ?? defaultKind(rel), scope, status: options.by ? 'verified' : options.status ?? 'accepted', sources: [rel], source_hash: sha256(split.body),
    ...(options.by ? { verified_at: now, verified_by: options.by } : {}),
  };
  const explicit = new Set(['id', 'sources', 'source_hash', ...(options.kind !== undefined ? ['kind'] : []), ...(options.scope !== undefined ? ['scope'] : []), ...(options.status !== undefined || options.by ? ['status', 'verified_by'] : [])]);
  const missing: Record<string, any> = {};
  const conflicts: Array<{ key: string; existing: any; requested: any }> = [];
  for (const [key, value] of Object.entries(desired)) {
    if (!(key in fields)) missing[key] = value;
    else if (explicit.has(key) && JSON.stringify(fields[key]) !== JSON.stringify(value)) conflicts.push({ key, existing: fields[key], requested: value });
  }
  const next = Object.keys(missing).length ? patchFrontmatter(text, missing) : text;
  const record = parseRecord(rel, next, ctx.repos, location, abs);
  if (record.state === 'invalid') throw new Error(`${rel} would not be a valid record:\n${record.problems.join('\n')}\nNothing was written.`);
  return { rel, abs, text, next, id, missing, conflicts, record };
}

const conflictLines = (conflicts: Array<{ key: string; existing: any; requested: any }>) => conflicts.map((c) => `- conflict ${c.key}: kept ${JSON.stringify(c.existing)} (requested ${JSON.stringify(c.requested)})${c.key === 'source_hash' ? ' — the body changed since it was hashed; review, then `agentos brain verify`' : ''}`);

export async function registerBrain(ctx: BrainCtx, pathArg: string | undefined, options: RegisterOptions) {
  if (!pathArg) throw new Error('Usage: agentos brain register <path> [--kind …] [--scope <repo-id|.>] [--status proposed|accepted] [--by <name>] [--dry-run] [--json]');
  const plan = await planRegister(ctx, await loadBrain(ctx.root, ctx.repos, ctx.vault), pathArg, options);
  const added = Object.keys(plan.missing);
  const data = { dryRun: Boolean(options.dryRun), path: plan.rel, record: publicRecord(plan.record), added, conflicts: plan.conflicts };
  if (!added.length) return out(options.json, true, data, [`AgentOS brain register: ${plan.rel} is already registered as ${plan.id} (no-op; nothing written).`, ...conflictLines(plan.conflicts)]);
  const stale = options.dryRun ? NO_COMMIT : await commit(ctx, () => writeFileAtomic(plan.abs, plan.next));
  return out(options.json, true, { ...data, ...stale.flags }, [
    `AgentOS brain register${options.dryRun ? ' (dry run)' : ''}: ${plan.rel} as ${plan.id}`,
    `${options.dryRun ? 'Would add' : 'Added'} frontmatter keys: ${added.join(', ')} (body untouched)`, ...conflictLines(plan.conflicts), ...stale.lines,
  ]);
}

const TEMPLATES: Array<{ name: string; kind: string; title: string; sections: string[] }> = [
  { name: 'architecture', kind: 'architecture', title: 'Architecture', sections: ['Overview', 'Components', 'Data flow', 'External dependencies'] },
  { name: 'conventions', kind: 'convention', title: 'Conventions', sections: ['Code style', 'Testing', 'Branching and commits', 'Naming'] },
  { name: 'glossary', kind: 'note', title: 'Glossary', sections: ['Terms'] },
];
const DECISIONS_TEMPLATE = { name: 'decisions', kind: 'decision', title: 'Decisions', sections: ['(first decision: date — subject)'] };

function templateText(template: typeof TEMPLATES[number], dir = BRAIN_DIR) {
  const rel = dir ? `${dir}/${template.name}.md` : `${template.name}.md`;
  const body = [`# ${template.title}`, '', ...template.sections.flatMap((section) => [`## ${section}`, '', UNKNOWN, ''])].join('\n');
  return { rel, text: patchFrontmatter(body, { id: `brain:${template.name}`, kind: template.kind, scope: '.', status: 'proposed', sources: [rel], source_hash: sha256(body) }) };
}

/** AgentOS-owned files adopted in place (frontmatter only) instead of a new template: `init` writes them. */
const OWNED: Record<string, string> = { decisions: '.agentos/decisions.md', architecture: '.agentos/architecture.md' };
/** Project docs that already cover a template: no template is created (no duplicate) and the doc is not edited;
 *  init names the `brain register` command instead. */
const COVERED: Record<string, string[]> = { architecture: ['ARCHITECTURE.md', 'docs/architecture.md'], conventions: ['CONVENTIONS.md', 'docs/conventions.md'], glossary: ['GLOSSARY.md', 'docs/glossary.md'] };

/** Creates the missing templates and adopts what exists: a record with the template id or kind, an AgentOS-owned
 *  file (registered in place) or a covering project doc (named, untouched). Repeatable: a set-up Brain is a no-op.
 *  A non-record file at a template path is refused, and then nothing is written. `agentos init` runs this too. */
export async function initBrain(ctx: BrainCtx, options: { dryRun?: boolean; json?: boolean; location?: string }) {
  const toVault = options.location === 'vault';
  if (options.location !== undefined && !['vault', 'workspace'].includes(options.location)) throw new Error('--location must be workspace or vault');
  if (toVault && ctx.vault?.canonical !== 'vault') throw new Error('brain init --location vault needs a linked Obsidian folder with knowledge.obsidian.canonical: vault (see `agentos obsidian link --canonical vault`). Nothing was written.');
  if (toVault && await vaultUnavailable(ctx.root, ctx.vault, ctx.vaultOff)) throw new Error(`vault unavailable: ${ctx.vault.dir}. Nothing was written.`);
  const records = await loadBrain(ctx.root, ctx.repos, ctx.vault);
  const base = toVault ? ctx.vault.vault : ctx.root;
  const found = (abs: string) => lstat(abs).then(() => true, () => false);
  const creates = [], registers = [], present = [], covered = [], existing = [];
  for (const template of [...TEMPLATES, DECISIONS_TEMPLATE]) {
    if (toVault && template === DECISIONS_TEMPLATE) continue; // decisions stay in the workspace
    const record = records.find((r) => r.id === `brain:${template.name}`);
    if (record) { present.push(`${record.id} (${record.path})`); continue; }
    if (!toVault && OWNED[template.name] && await found(join(ctx.root, OWNED[template.name]))) {
      const plan = await planRegister(ctx, records, join(ctx.root, OWNED[template.name]), { kind: template.kind, ...(template.name === 'architecture' ? { status: 'proposed' } : {}) });
      if (Object.keys(plan.missing).length) registers.push(plan); else present.push(`${plan.id} (${plan.rel})`);
      continue;
    }
    const sameKind = template.kind !== 'note' && records.find((r) => r.kind === template.kind && r.state !== 'invalid');
    if (sameKind) { present.push(`${sameKind.id} (${sameKind.path}, ${template.kind})`); continue; }
    const doc = toVault ? undefined : (await Promise.all((COVERED[template.name] ?? []).map(async (rel) => (await found(join(ctx.root, rel)) ? rel : null)))).find(Boolean);
    if (doc) { covered.push({ rel: doc, kind: template.kind }); continue; }
    const file = templateText(template, toVault ? (ctx.vault.dest === '.' ? '' : ctx.vault.dest) : BRAIN_DIR);
    if (await found(join(base, file.rel))) existing.push(file.rel); else creates.push(file);
  }
  if (existing.length) return out(options.json, false, { existing }, ['AgentOS brain init: FAIL', ...existing.map((rel) => `- ${rel} exists; refusing to overwrite it.`), 'Nothing was written. Register existing files with `agentos brain register <path>`.']);
  const stale = options.dryRun || (!creates.length && !registers.length) ? NO_COMMIT : await commit(ctx, async () => {
    if (creates.length) await mkdirTracked(toVault ? ctx.vault.dir : join(ctx.root, BRAIN_DIR));
    for (const file of creates) if (!(await writeFileExclusiveAtomic(join(base, file.rel), Buffer.from(file.text))).created) throw new Error(`${file.rel} appeared while writing; nothing was written.`);
    for (const plan of registers) await writeFileAtomic(plan.abs, plan.next);
  });
  const verb = options.dryRun ? 'Would create' : 'Created';
  return out(options.json, true, { dryRun: Boolean(options.dryRun), created: creates.map((file) => file.rel), registered: registers.map((plan) => plan.rel), present, covered: covered.map((doc) => doc.rel), ...stale.flags }, [
    `AgentOS brain init${options.dryRun ? ' (dry run)' : ''}${toVault ? ` into the linked vault folder ${ctx.vault.dir} (paths below are vault-relative)` : ''}`,
    ...creates.map((file) => `- ${verb}: ${file.rel} (status: proposed; sections marked ${UNKNOWN})`),
    ...registers.map((plan) => `- ${options.dryRun ? 'Would register' : 'Registered'}: ${plan.rel} as ${plan.id} (existing file; frontmatter only, not duplicated)`),
    ...present.map((entry) => `- Present: ${entry} (kept as is)`),
    ...covered.map((doc) => `- Found ${doc.rel}: not duplicated and not edited; adopt it with \`agentos brain register ${doc.rel} --kind ${doc.kind}\``),
    ...stale.lines,
  ]);
}

// --- read-only views --------------------------------------------------------------------------------

export async function listBrain(ctx: BrainCtx, options: { status?: string; kind?: string; json?: boolean }) {
  const all = await loadBrain(ctx.root, ctx.repos, ctx.vault);
  const records = all.filter((record) => (!options.status || record.status === options.status) && (!options.kind || record.kind === options.kind));
  const groups = await unreadableKnowledge(ctx.root, all, ctx.vault, ctx.vaultOff);
  const lines = records.map((record) => `- ${record.id ?? '(no id)'} [${record.status}${record.state === 'changed' ? ', source changed since verification' : ''}] ${record.kind ?? '?'} ${record.path}${record.location === 'vault' ? ` (vault: ${record.abs})` : ''} — ${record.title}`);
  for (const gone of groups) for (const record of gone.records) lines.push(`- ${record.id} [${record.state}] ${record.kind} ${record.path}: ${gone.reason} — ${record.title}`);
  for (const gone of groups) if (gone.failed && !gone.records.length) lines.push(`- ${gone.reason}; no records known there`);
  return out(options.json, true, { records: [...records.map(publicRecord), ...groups.flatMap((gone) => gone.records)] }, lines.length ? lines
    : ['No Brain records. Start with `agentos brain init` or `agentos brain register <path>`.']);
}

export async function showBrain(ctx: BrainCtx, ref: string | undefined, options: { json?: boolean }) {
  if (!ref) throw new Error('Usage: agentos brain show <id-or-path> [--json]');
  const record = findRecord(await loadBrain(ctx.root, ctx.repos, ctx.vault), ctx, ref);
  if (!record) return out(options.json, false, {}, [`No Brain record ${ref}. List them with \`agentos brain list\`.`]);
  const data = { record: { ...record.fields, id: record.id, path: record.path, ...(record.location === 'vault' ? { location: 'vault', abs: record.abs } : {}), title: record.title, state: record.state, status: record.status, current_hash: record.current_hash, problems: record.problems } };
  return out(options.json, true, data, [
    `${record.id ?? '(no id)'} — ${record.title}`, `Path: ${record.path}`,
    ...(record.location === 'vault' ? [`Location: vault (portable path above is vault-relative); on this machine: ${record.abs} (binding: .agentos/project.yaml knowledge.obsidian.vault)`] : []),
    `Status: ${record.status}; kind: ${record.kind ?? '?'}; scope: ${record.scope ?? '?'}; state: ${record.state}`,
    ...(record.fields.superseded_by ? [`Superseded by: ${record.fields.superseded_by}`] : []),
    ...record.problems.map((problem) => `Problem: ${problem}`), '', record.body.trimEnd(),
  ]);
}

/** Same term matching as the context builder (taskTerms/termHits over the id slug, title and kind). */
export async function searchBrain(ctx: BrainCtx, query: string, options: { json?: boolean }) {
  const terms = taskTerms(query);
  if (!terms.length) throw new Error('Usage: agentos brain search <terms…> (terms of 3+ letters)');
  const rank = (record: BrainRecord) => (record.status === 'superseded' ? 2 : record.status === 'proposed' ? 1 : 0);
  const hits = valid(await loadBrain(ctx.root, ctx.repos, ctx.vault))
    .map((record) => ({ record, matched: termHits(terms, `${record.id.slice(record.id.indexOf(':') + 1)} ${record.title} ${record.kind}`) }))
    .filter((hit) => hit.matched.length)
    .sort((a, b) => b.matched.length - a.matched.length || rank(a.record) - rank(b.record));
  return out(options.json, true, { terms, records: hits.map((hit) => ({ ...publicRecord(hit.record), matched: hit.matched })) },
    hits.length ? hits.map((hit) => `- ${hit.record.id} [${hit.record.status}] ${hit.record.path} — ${hit.record.title} (matched: ${hit.matched.join(', ')})`) : [`No Brain record matches ${terms.join(', ')}.`]);
}

const CHANGED = 'source changed since verification — recheck (a hash change says the text changed, not that it is wrong)';

/** Exit 1 on `invalid`, and on records last known under a path that fails to read (permission/I/O error): those
 *  are not reported as fine. `unavailable` (vault folder absent, integration off) is reported, like doctor's warning. */
export async function checkBrain(ctx: BrainCtx, options: { json?: boolean }) {
  const records = await loadBrain(ctx.root, ctx.repos, ctx.vault);
  const groups = await unreadableKnowledge(ctx.root, records, ctx.vault, ctx.vaultOff);
  const gone = groups.find((group) => group.vault) ?? null;
  const lost = groups.flatMap((group) => group.records);
  const invalid = records.filter((record) => record.state === 'invalid');
  const count = (state: string) => lost.filter((record) => record.state === state).length;
  const ok = invalid.length === 0 && !groups.some((group) => group.failed && group.records.length);
  return out(options.json, ok, { ...(gone ? { vault_unavailable: gone.dir ?? gone.reason } : {}), records: [...records.map((record) => ({ ...publicRecord(record), source_hash: record.source_hash, current_hash: record.current_hash, problems: record.problems })), ...lost] }, [
    `AgentOS brain check: ${records.length + lost.length} record(s), ${records.filter((r) => r.state === 'ok').length} ok, ${records.filter((r) => r.state === 'changed').length} changed, ${invalid.length} invalid${gone ? `, ${count('unavailable')} unavailable` : ''}${count('unreadable') ? `, ${count('unreadable')} unreadable` : ''}`,
    ...records.map((record) => record.state === 'ok' ? `- ok ${record.id} (${record.path})`
      : record.state === 'changed' ? `- changed ${record.id} (${record.path}): ${CHANGED}; after review run \`agentos brain verify ${record.id} --by <name>\``
        : `- invalid ${record.path}: ${record.problems.join('; ')} (file left as is; fix it by hand)`),
    ...groups.flatMap((group) => [...group.records.map((record) => `- ${record.state} ${record.id} (${record.path}): ${group.reason}`), ...(group.records.length ? [] : [`- ${group.reason}; no records known there`])]),
  ]);
}

/** Doctor: invalid metadata is a problem, a changed source or an unavailable vault folder a warning. */
export async function brainDoctor(root: string, repos: string[], vault?: VaultBinding | null, off?: string | null) {
  const records = await loadBrain(root, repos, vault);
  const groups = await unreadableKnowledge(root, records, vault, off);
  return {
    problems: records.filter((record) => record.state === 'invalid').flatMap((record) => record.problems.map((problem) => `Brain record ${problem}`)),
    warnings: [
      ...records.filter((record) => record.state === 'changed').map((record) => `Brain record ${record.id} (${record.path}): ${CHANGED}; run \`agentos brain verify ${record.id}\` after review`),
      ...groups.map((gone) => `${gone.vault && gone.dir ? `Obsidian ${gone.reason}${gone.absent ? ' (absent or not mounted)' : ''}` : gone.reason}; ${gone.records.length ? `${gone.records.length} Brain record(s) last known there cannot be read and \`agentos context\` lists them under Missing` : 'no records known there'}`),
    ],
  };
}

// --- verify -----------------------------------------------------------------------------------------

export async function verifyBrain(ctx: BrainCtx, ref: string | undefined, options: { by?: string; dryRun?: boolean; json?: boolean }) {
  if (!ref) throw new Error('Usage: agentos brain verify <id-or-path> [--by <name>] [--dry-run]');
  const record = findRecord(await loadBrain(ctx.root, ctx.repos, ctx.vault), ctx, ref);
  if (!record) throw new Error(`No Brain record ${ref}.`);
  if (record.state === 'invalid') throw new Error(`${record.path} has invalid metadata:\n${record.problems.join('\n')}\nFix it by hand first. Nothing was written.`);
  const now = new Date().toISOString();
  const by = options.by || 'unknown';
  const next = patchFrontmatter(record.text, {
    status: record.status === 'superseded' ? 'superseded' : 'verified', verified_at: now, verified_by: by, source_hash: record.current_hash,
    history: [...(record.fields.history ?? []), `${now} verified by ${by}: ${short(record.source_hash)} -> ${short(record.current_hash)}`],
  });
  const stale = options.dryRun ? NO_COMMIT : await commit(ctx, () => writeFileAtomic(record.abs, next));
  return out(options.json, true, { dryRun: Boolean(options.dryRun), id: record.id, path: record.path, source_hash: record.current_hash, ...stale.flags }, [
    `AgentOS brain verify${options.dryRun ? ' (dry run)' : ''}: ${record.id} (${record.path})`,
    `${options.dryRun ? 'Would record' : 'Recorded'} verified_by ${by}; source_hash ${short(record.source_hash)} -> ${short(record.current_hash)}${record.state === 'ok' ? ' (unchanged)' : ''}`, ...stale.lines,
  ]);
}

/** Inspect policy without changing project configuration or records. */
export function policyBrain(ctx: BrainCtx, options: { json?: boolean }) {
  const parsed = parseApprovalPolicy(ctx.approval);
  return out(options.json, !parsed.errors.length, { policy: parsed.policy, policy_hash: parsed.errors.length ? null : parsed.hash,
    errors: parsed.errors, limits: { append_bytes: AUTO_APPEND_BYTES, record_bytes: AUTO_RECORD_BYTES }, authentication: false }, [
    `AgentOS Brain approval: ${parsed.errors.length ? 'INVALID (automatic application disabled)' : parsed.policy.mode}`,
    `Actors: ${parsed.policy.actors.join(', ') || '(none)'}`, `Records: ${parsed.policy.records.join(', ') || '(none)'}`,
    ...parsed.errors, 'Only the owner configures knowledge.brain.approval in project.yaml. Names are supplied labels, not authenticated identities.',
    'Agents apply only with --auto --by <self>; refusals remain pending for owner review. This policy is not a sandbox.',
  ]);
}

// --- proposals --------------------------------------------------------------------------------------

interface Proposal { rel: string; applied: boolean; text: string; fields: Record<string, any>; body: string; problems: string[] }

async function loadProposal(ctx: BrainCtx, ref: string): Promise<Proposal> {
  const name = basename(ref).replace(/(\.md)?$/i, '.md');
  const asPath = posix(relative(ctx.root, resolve(ctx.cwd, ref)));
  const candidates = [asPath, `${PROPOSALS}/${name}`, `${APPLIED}/${name}`].filter((rel) => rel.startsWith(`${PROPOSALS}/`));
  const applied = await lstat(join(ctx.root, APPLIED, name)).then((info) => info.isFile(), () => false);
  for (const rel of candidates) {
    const info = await lstat(join(ctx.root, rel)).catch(() => null);
    if (!info?.isFile()) continue;
    const text = await readUtf8(join(ctx.root, rel));
    const split = splitFrontmatter(text);
    const parsed = split.closed ? parseFields(rel, split.fm, PROPOSAL_KEYS) : { fields: {}, problems: [`${rel}:1: proposal frontmatter is missing or not closed`] };
    return { rel, applied: applied || rel.startsWith(`${APPLIED}/`), text, fields: parsed.fields, body: split.body, problems: parsed.problems };
  }
  throw new Error(`No proposal ${ref} under ${PROPOSALS}/.`);
}

const asList = (value: unknown): string[] => (value === undefined || value === null ? [] : Array.isArray(value) ? value.map(String) : [String(value)]);

/** Every check `apply` runs. Rejections block; flags (ambiguous conflicts) are reported, never auto-resolved. */
function validateProposal(ctx: BrainCtx, records: BrainRecord[], proposal: Proposal) {
  const rejections: Array<{ check: string; message: string }> = [];
  const flags: Array<{ check: string; message: string; ids: string[] }> = [];
  const reject = (check: string, message: string) => rejections.push({ check, message });
  const f = proposal.fields;
  for (const problem of proposal.problems) reject('schema', problem);
  for (const key of ['applied_at', 'applied_by', 'approval_mode', 'approval_policy_hash']) {
    if (f[key] !== undefined) reject('schema', `${proposal.rel}: ${key} is written only when a proposal is applied`);
  }
  if (f.status !== 'proposed' && !proposal.problems.length) reject('schema', `${proposal.rel}: status is ${JSON.stringify(f.status)}, expected proposed`);
  if (!['replace', 'append'].includes(f.mode)) reject('schema', `${proposal.rel}: mode must be replace or append`);
  if (!proposal.body.trim()) reject('schema', `${proposal.rel}: the proposal has no content`);
  if (splitFrontmatter(proposal.body).has) reject('schema', `${proposal.rel}: proposal content must not carry its own frontmatter; metadata is managed by agentos brain`);
  if (['task', 'checkpoint'].some((key) => f[key] !== undefined && typeof f[key] !== 'string') || (f.evidence !== undefined && (!Array.isArray(f.evidence) || !f.evidence.every((line) => typeof line === 'string')))) reject('schema', `${proposal.rel}: task and checkpoint must be strings, evidence a list of strings`);
  const target = records.find((record) => record.id === f.target);
  if (!target) { reject('identity', `target ${f.target} does not exist`); return { rejections, flags, target: null, newBody: null, supersede: [] }; }
  if (f.target_path !== target.path) reject('identity', `target ${f.target} is ${target.path}, the proposal says ${f.target_path}`);
  if (target.state === 'invalid') reject('schema', `target metadata is invalid: ${target.problems.join('; ')}`);
  if (target.scope !== '.' && !ctx.repos.includes(target.scope)) reject('scope', `target scope ${target.scope} is not . or a repo of this project`);
  const supersede: BrainRecord[] = [];
  for (const id of asList(f.supersedes)) {
    const old = records.find((record) => record.id === id);
    if (!old) reject('references', `supersedes ${id}: no such record`);
    else if (old === target) reject('references', `a record cannot supersede itself (${id})`);
    else if (old.state === 'invalid') reject('references', `supersedes ${id}: its metadata is invalid`);
    else supersede.push(old);
  }
  // Name each actual cause: a base that no longer matches, and/or a body edited since verification.
  const causes = [
    ...(f.base_hash !== target.source_hash ? [`the target was re-verified after this proposal was written (base_hash ${f.base_hash}, target source_hash now ${target.source_hash}): propose again from the current text`] : []),
    ...(target.current_hash !== target.source_hash ? [`the target body was edited since verification (verified source_hash ${target.source_hash}, body now hashes to ${target.current_hash}): review, then \`agentos brain verify ${target.id}\` and propose again`] : []),
  ];
  if (causes.length) reject('stale', `stale write: ${causes.join('; ')}`);
  const content = proposal.body;
  const newBody = f.mode === 'append' ? `${target.body}${target.body.endsWith('\n') ? '\n' : '\n\n'}${content}` : content;
  const dup = f.mode === 'append' ? (norm(target.body).includes(norm(content)) ? target : null) : (norm(content) === norm(target.body) ? target : null);
  const other = records.find((record) => record !== target && record.state !== 'invalid' && norm(record.body) === norm(content));
  if (dup || other) reject('duplicate', `exact duplicate: the same normalized text is already in ${(dup ?? other).id} (${(dup ?? other).path})`);
  const title = f.mode === 'replace' ? markdownHeadings(content).find((heading) => heading.level === 1)?.title ?? target.title : target.title;
  const subject = subjectOf(target.fields.title ?? title);
  const same = valid(records).filter((record) => record !== target && !supersede.includes(record) && record.kind === target.kind && ['accepted', 'verified'].includes(record.status) && subjectOf(record.title) === subject);
  if (subject && same.length) flags.push({ check: 'conflict', message: `ambiguous: ${same.map((record) => record.id).join(', ')} (${target.kind}) has the same subject "${subject}"; resolve by hand (supersede one, or reword)`, ids: same.map((record) => record.id) });
  return { rejections, flags, target, newBody, supersede };
}

export function diffLines(before: string, after: string) {
  const a = before.split('\n'), b = after.split('\n');
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) start++;
  let endA = a.length, endB = b.length;
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) { endA--; endB--; }
  return [`@@ line ${start + 1} @@`, ...a.slice(start, endA).map((line) => `-${line}`), ...b.slice(start, endB).map((line) => `+${line}`)];
}

function validationLines(result: ReturnType<typeof validateProposal>) {
  return [
    ...(result.rejections.length ? result.rejections.map((item) => `- REJECTED (${item.check}): ${item.message}`) : ['- all checks passed (identity, scope, schema, references, duplicate, stale)']),
    ...result.flags.map((item) => `- FLAG (${item.check}): ${item.message}`),
  ];
}

function planLines(proposal: Proposal, result: ReturnType<typeof validateProposal>) {
  const { target } = result;
  if (!target) return [];
  const newHash = sha256(result.newBody);
  return [
    `Target: ${target.id} (${target.path})`,
    `Change: ${proposal.fields.mode === 'append' ? 'append section' : 'replace body'}${proposal.fields.summary ? ` — ${proposal.fields.summary}` : ''}`,
    ...(proposal.fields.checkpoint ? [`Checkpoint: ${proposal.fields.checkpoint} (task ${proposal.fields.task})`, `Evidence: ${asList(proposal.fields.evidence).join('; ') || '(none)'}`] : []),
    'Frontmatter:',
    `- status: ${target.status} -> accepted`, `- source_hash: ${short(target.source_hash)} -> ${short(newHash)}`, '- updated_at: now', `- history: + ${proposal.rel}`,
    ...(result.supersede.length ? [`- supersedes: + ${result.supersede.map((record) => record.id).join(', ')}`] : []),
    ...result.supersede.map((record) => `Supersession: ${record.id} (${record.path}): status ${record.status} -> superseded, superseded_by ${target.id}`),
    `Proposal: ${proposal.rel} -> ${APPLIED}/${basename(proposal.rel)}`,
    'Body diff:', ...diffLines(target.body, result.newBody),
  ];
}

interface ProposeOptions { from?: string; summary?: string; supersedes?: string; append?: boolean; by?: string; task?: string; dryRun?: boolean; json?: boolean; stdin?: () => Promise<string> }

export async function proposeBrain(ctx: BrainCtx, ref: string | undefined, options: ProposeOptions) {
  if (!ref || !options.from) throw new Error('Usage: agentos brain propose <id-or-path> --from <file|-> [--summary "<text>"] [--supersedes <id>[,<id>]] [--append] [--by <name>] [--task <id>] [--dry-run] [--json]');
  const records = await loadBrain(ctx.root, ctx.repos, ctx.vault);
  const target = findRecord(records, ctx, ref);
  if (!target) throw new Error(`No Brain record ${ref}; register the file first (\`agentos brain register <path>\`).`);
  if (!target.id) throw new Error(`${target.path} has invalid metadata; fix it first.`);
  const content = options.from === '-' ? await options.stdin() : await readUtf8(resolve(ctx.cwd, options.from));
  if (Buffer.byteLength(content) > MAX_BYTES) throw new Error(`proposal content is larger than ${MAX_BYTES} bytes.`);
  if (splitFrontmatter(content).has) throw new Error('Proposal content must be the Markdown body only, without frontmatter (metadata is managed by agentos brain). Nothing was written.');
  // --task: tie the proposal to the task's current checkpoint (goal Slice 5). The engine decides that knowledge
  // changed; AgentOS only refuses progress-only checkpoints and keys the file so the same event stages once.
  let tie: { task: string; checkpoint: string; evidence: string[] } | null = null;
  if (options.task !== undefined) {
    const task = slugTask(options.task);
    if (!task) throw new Error('--task must contain letters or digits.');
    const loaded = await loadCurrent(ctx.root, task);
    const refuse = (reason: string, checkpoint: string | null = null) => out(options.json, false, { task, checkpoint, staged: false, reason }, ['AgentOS brain propose: NOTHING STAGED', reason, 'Nothing was written.']);
    if (loaded.kind !== 'ok') return refuse(loaded.kind === 'none' ? `No checkpoint for task ${task}; write one first: \`agentos checkpoint --task ${task} --progress "<done>" --check "<cmd>"\`.` : `The checkpoint of task ${task} is incomplete (${loaded.evidence.reason}); see \`agentos resume --task ${task}\`.`);
    const evidence = checkpointEvidence(loaded.record);
    if (!evidence.meaningful) return refuse(`Checkpoint ${loaded.record.id} (task ${task}) records no changed file and no observed-pass check (progress only); a durable-knowledge proposal needs that evidence.`, loaded.record.id);
    tie = { task, checkpoint: loaded.record.id, evidence: evidence.lines };
  }
  const now = new Date();
  const supersedes = options.supersedes ? options.supersedes.split(',').map((id) => id.trim()).filter(Boolean) : [];
  const fields = {
    target: target.id, target_path: target.path, base_hash: target.source_hash, proposed_by: options.by || process.env.AGENTOS_ENGINE || 'unknown', status: 'proposed',
    mode: options.append ? 'append' : 'replace', ...(options.summary ? { summary: options.summary } : {}), ...(supersedes.length ? { supersedes } : {}), ...(tie ?? {}), created_at: now.toISOString(),
  };
  const name = tie
    ? `${tie.task}-${sha256(JSON.stringify([target.id, tie.checkpoint, fields.mode, norm(content), supersedes])).slice(0, 12)}-${target.id.slice('brain:'.length)}.md`
    : `${now.toISOString().replace(/[:.]/g, '-')}-${target.id.slice('brain:'.length)}.md`;
  const rel = `${PROPOSALS}/${name}`;
  // Same checkpoint, target, mode and text = the same event: report the existing proposal (pending or applied).
  for (const seen of tie ? [rel, `${APPLIED}/${name}`] : []) {
    if (await lstat(join(ctx.root, seen)).then((info) => info.isFile(), () => false)) {
      return out(options.json, true, { dryRun: Boolean(options.dryRun), duplicate: true, path: seen, proposal: fields }, [`AgentOS brain propose: already staged as ${seen} (same checkpoint, target and text); nothing written.`]);
    }
  }
  const text = patchFrontmatter(content, fields);
  const proposal: Proposal = { rel, applied: false, text, fields, body: content, problems: [] };
  const result = validateProposal(ctx, records, proposal);
  const data = { dryRun: Boolean(options.dryRun), path: rel, proposal: fields, rejections: result.rejections, flags: result.flags };
  if (result.rejections.length) return out(options.json, false, data, ['AgentOS brain propose: REJECTED', ...validationLines(result), 'Nothing was written.']);
  if (!options.dryRun) {
    await withMutationTransaction(async () => {
      await mkdirTracked(join(ctx.root, PROPOSALS));
      if (!(await writeFileExclusiveAtomic(join(ctx.root, rel), Buffer.from(text))).created) throw new Error(`${rel} already exists; nothing was written.`);
    });
  }
  return out(options.json, true, data, [
    `AgentOS brain propose${options.dryRun ? ' (dry run)' : ''}: ${options.dryRun ? 'would write' : 'wrote'} ${rel}`,
    `Target: ${target.id} (${target.path}); base_hash ${short(target.source_hash)}; proposed_by ${fields.proposed_by}`, ...validationLines(result),
    `Next: agentos brain preview ${rel}`,
    'Agents: inspect `agentos brain policy`. Only an owner-enabled policy permits `agentos brain apply <proposal> --auto --by <self>`; a refusal stays pending. Never drop --auto to bypass review.',
  ]);
}

async function autoReview(ctx: BrainCtx, proposal: Proposal, records: BrainRecords, result: ReturnType<typeof validateProposal>, actor?: string) {
  const incomplete = Boolean(records.unreadable?.length) || records.some((record) => record.state === 'invalid')
    || (await brainMissing(ctx.root, records, ctx.vault, ctx.vaultOff)).length > 0
    || (await lastKnown(ctx.root)).some((known) => !records.some((record) => record.id === known.id && record.path === known.path && record.location === (known.location ?? 'workspace')));
  return automaticApproval(ctx, proposal, result.target, result.newBody, actor, { ...result, incomplete });
}

export async function previewBrain(ctx: BrainCtx, ref: string | undefined, options: { json?: boolean; auto?: boolean; by?: string }) {
  if (!ref) throw new Error('Usage: agentos brain preview <proposal> [--json]');
  const proposal = await loadProposal(ctx, ref);
  if (proposal.applied) return out(options.json, true, { applied: true, path: proposal.rel }, [`${proposal.rel}: already applied; nothing to preview.`]);
  const records = await loadBrain(ctx.root, ctx.repos, ctx.vault);
  const result = validateProposal(ctx, records, proposal);
  const approval = options.auto ? await autoReview(ctx, proposal, records, result, options.by) : null;
  return out(options.json, !approval || approval.eligible, { path: proposal.rel, target: result.target?.id ?? null, rejections: result.rejections, flags: result.flags, supersedes: result.supersede.map((record) => record.id), new_body: result.newBody, ...(approval ? { approval } : {}) },
    [`AgentOS brain preview: ${proposal.rel} (read-only)`, ...planLines(proposal, result), 'Validation:', ...validationLines(result), ...approvalLines(approval)]);
}

export async function validateBrain(ctx: BrainCtx, ref: string | undefined, options: { json?: boolean; auto?: boolean; by?: string }) {
  if (!ref) throw new Error('Usage: agentos brain validate <proposal> [--json]');
  const proposal = await loadProposal(ctx, ref);
  if (proposal.applied) return out(options.json, true, { applied: true, path: proposal.rel, rejections: [], flags: [] }, [`${proposal.rel}: already applied.`]);
  const records = await loadBrain(ctx.root, ctx.repos, ctx.vault);
  const result = validateProposal(ctx, records, proposal);
  const approval = options.auto ? await autoReview(ctx, proposal, records, result, options.by) : null;
  const ok = result.rejections.length === 0 && (!approval || approval.eligible);
  return out(options.json, ok, { path: proposal.rel, target: result.target?.id ?? null, rejections: result.rejections, flags: result.flags, ...(approval ? { approval } : {}) },
    [`AgentOS brain validate: ${proposal.rel}: ${ok ? 'OK' : 'REJECTED'}`, ...validationLines(result), ...approvalLines(approval)]);
}

/** Manual application remains the owner workflow; --auto adds a policy check, never authentication. */
const approvalLines = (approval: Awaited<ReturnType<typeof automaticApproval>> | null) => approval
  ? [`Automatic application: ${approval.eligible ? 'ELIGIBLE' : 'REVIEW REQUIRED'}`, ...approval.reasons.map((reason) => `- ${reason}`)] : [];

export async function applyBrain(ctx: BrainCtx, ref: string | undefined, options: { by?: unknown; auto?: boolean; dryRun?: boolean; json?: boolean }) {
  if (!ref) throw new Error('Usage: agentos brain apply <proposal> --by <actor> [--auto] [--dry-run] [--json]');
  const by = typeof options.by === 'string' ? options.by.trim() : '';
  if (!by && !options.dryRun) throw new Error('agentos brain apply needs --by <owner>: the applier is recorded in history. Agents use --auto with their own allowed identity; without --auto application requires owner review. Nothing was written.');
  const proposal = await loadProposal(ctx, ref);
  if (proposal.applied) return out(options.json, true, { applied: true, noop: true, path: `${APPLIED}/${basename(proposal.rel)}` }, [`AgentOS brain apply: ${basename(proposal.rel)} was already applied (${APPLIED}/); no-op, nothing written.`]);
  const records = await loadBrain(ctx.root, ctx.repos, ctx.vault);
  const result = validateProposal(ctx, records, proposal);
  const approval = options.auto ? await autoReview(ctx, proposal, records, result, by) : null;
  const data = { dryRun: Boolean(options.dryRun), path: proposal.rel, target: result.target?.id ?? null, rejections: result.rejections, flags: result.flags, ...(approval ? { approval } : {}) };
  if (result.rejections.length || (approval && !approval.eligible)) return out(options.json, false, { ...data, review_required: Boolean(approval && !approval.eligible) }, ['AgentOS brain apply: REFUSED', ...validationLines(result), ...approvalLines(approval), 'Nothing was written; leave the proposal pending for owner review.']);
  const { target } = result;
  const now = new Date().toISOString();
  const newHash = sha256(result.newBody);
  const split = splitFrontmatter(target.text);
  const supersedes = [...new Set([...asList(target.fields.supersedes), ...result.supersede.map((record) => record.id)])];
  const targetText = patchFrontmatter(`${split.head}${split.fm}${split.close}${result.newBody}`, {
    status: 'accepted', source_hash: newHash, updated_at: now, ...(supersedes.length ? { supersedes } : {}),
    history: [...(target.fields.history ?? []), `${now} applied ${proposal.rel} by ${by || '(--by not set)'} (proposed by ${proposal.fields.proposed_by ?? 'unknown'}): ${short(target.source_hash)} -> ${short(newHash)}${approval ? `; approval auto-append (${approval.policy_hash})` : ''}`],
  });
  const appliedRel = `${APPLIED}/${basename(proposal.rel)}`;
  const appliedText = patchFrontmatter(proposal.text, { status: 'applied', applied_at: now, applied_by: by || '(--by not set)', approval_mode: approval ? 'auto-append' : 'manual', ...(approval ? { approval_policy_hash: approval.policy_hash } : {}) });
  const stale = options.dryRun ? NO_COMMIT : await commit(ctx, async () => {
    await writeFileAtomic(target.abs, targetText);
    for (const old of result.supersede) await writeFileAtomic(old.abs, patchFrontmatter(old.text, { status: 'superseded', superseded_by: target.id, updated_at: now }));
    await mkdirTracked(join(ctx.root, APPLIED));
    if (!(await writeFileExclusiveAtomic(join(ctx.root, appliedRel), Buffer.from(appliedText))).created) throw new Error(`${appliedRel} already exists; nothing was written.`);
    await removeTracked(join(ctx.root, proposal.rel));
  });
  return out(options.json, true, { ...data, applied_path: appliedRel, applied_by: by || null, source_hash: newHash, ...stale.flags }, [
    `AgentOS brain apply${options.dryRun ? ' (dry run; nothing written)' : ''}: ${proposal.rel}`, ...planLines(proposal, result),
    `Applied by: ${by || '(not set; a real apply needs --by <owner>)'} (proposed by ${proposal.fields.proposed_by ?? 'unknown'})`, 'Validation:', ...validationLines(result),
    ...(stale.flags.index_stale ? [] : [`${options.dryRun ? 'Would regenerate' : 'Regenerated'}: ${INDEX}`]), ...stale.lines, SINGLE_WRITER,
  ]);
}
